-- Royal Diadem: import the 204 jewellery products already on the website into the database
-- so they appear in the admin dashboard (Products tab) where they can be edited, re-priced or deleted.
-- Run once in Supabase > SQL Editor. Safe to re-run: products whose image is already imported are skipped.
insert into products (name, category, image_url, in_stock)
